use mill.stock;
use mill.rules;

fn lines() -> String {
    let inventory = mill.stock.inventory();
    var result = "";
    var first = true;
    var i = 0;
    while i < inventory.len() {
        let plank = inventory[i];
        if mill.rules.is_kept(plank) {
            let label = mill.rules.label(plank);
            if first {
                result = label;
                first = false;
            } else {
                result = result.concat(other: ",");
                result = result.concat(other: label);
            }
        }
        i = i + 1;
    }
    return result;
}

