use harbor.signal;

fn entries() -> String {
    var result = "";
    var first = true;
    for s in harbor.signal.signals() {
        let rendered = match s {
            Calm => "calm",
            Gale(speed) => "gale:".concat(other: speed.to_text()),
            Fog(word) => "fog:".concat(other: word),
        };
        if first {
            result = rendered;
            first = false;
        } else {
            result = result.concat(other: ";");
            result = result.concat(other: rendered);
        }
    }
    return result;
}

use harbor.signal;

pub fn entries() -> String {
    var result = "";
    var i = 0;
    let total = harbor.signal.len();
    while i < total {
        let s = harbor.signal.get(index: i);
        let rendered = match s {
            Calm => "calm",
            Gale(speed) => "gale:".concat(other: speed.to_text()),
            Fog(word) => "fog:".concat(other: word),
        };
        if i > 0 {
            result = result.concat(other: ";");
        }
        result = result.concat(other: rendered);
        i = i + 1;
    }
    return result;
}

