                }
            },
            None => {
                running = false;
            },
        }
    }
    return result;
}

use relay.feed;

fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    var total = 0;
    for frame in relay.feed.frames() {
        let value = match relay.feed.decode(frame) {
            Ok(v) => v,
            Err(_) => 0,
        };
        total = total + value;
    }
    relay.feed.emit(total: total, io: io)?;
    return Ok(unit);
}

